{
  "id": "f123f2a7-ade5-422f-ba52-048df8bffbbe",
  "version": "1.9",
  "name": "VendorApproval",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "aeda2806-4db8-49c7-9c5d-c3de52d5a754",
        "isDefaultEntryPoint": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the process.",
          "source": "null",
          "var": "output"
        }
      }
    },
    {
      "id": "vendorContext1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": { "label": "Set Vendor Context" },
      "inputs": {
        "script": "return { vendorName: \"Acme Corp\", creditScore: 720 };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "complianceReview1",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": { "label": "Compliance Review" },
      "inputs": {
        "title": "Vendor Compliance Review",
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        },
        "priority": "Medium",
        "schema": {
          "schemaId": "e7a1c9d2-4b6f-4e21-9a3d-6f2b8c1e5a90",
          "fields": [
            {
              "id": "vendorname",
              "label": "Vendor Name",
              "type": "string",
              "direction": "input",
              "binding": "vars.vendorContext1.output.vendorName"
            },
            {
              "id": "creditscore",
              "label": "Credit Score",
              "type": "number",
              "direction": "input",
              "binding": "vars.vendorContext1.output.creditScore"
            },
            {
              "id": "approved",
              "label": "Approved",
              "type": "boolean",
              "direction": "output",
              "variable": "vars.approved",
              "required": true
            },
            {
              "id": "risknotes",
              "label": "Risk Notes",
              "type": "string",
              "direction": "output",
              "variable": "vars.riskNotes"
            }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true, "action": "Continue" },
            { "id": "reject", "name": "Reject", "type": "string", "isPrimary": false, "action": "End" }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "approved": { "type": "boolean" },
            "risknotes": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "approvalDecision1",
      "type": "core.logic.decision",
      "typeVersion": "1.2",
      "display": { "label": "Approved?" },
      "inputs": {
        "expression": "$vars.complianceReview1.output.approved",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "onboardLog1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": { "label": "Log Vendor Onboarded" },
      "inputs": {
        "script": "return { message: \"Vendor onboarded\" };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "rejectLog1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": { "label": "Log Vendor Rejected" },
      "inputs": {
        "script": "return { message: \"Vendor rejected\" };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endSuccess1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "Onboarding Complete" },
      "inputs": {}
    },
    {
      "id": "endRejected1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "Onboarding Rejected" },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "edge_start_output_vendorContext1_input",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "vendorContext1",
      "targetPort": "input"
    },
    {
      "id": "edge_vendorContext1_success_complianceReview1_input",
      "sourceNodeId": "vendorContext1",
      "sourcePort": "success",
      "targetNodeId": "complianceReview1",
      "targetPort": "input"
    },
    {
      "id": "edge_complianceReview1_completed_approvalDecision1_input",
      "sourceNodeId": "complianceReview1",
      "sourcePort": "completed",
      "targetNodeId": "approvalDecision1",
      "targetPort": "input"
    },
    {
      "id": "edge_approvalDecision1_true_onboardLog1_input",
      "sourceNodeId": "approvalDecision1",
      "sourcePort": "true",
      "targetNodeId": "onboardLog1",
      "targetPort": "input"
    },
    {
      "id": "edge_approvalDecision1_false_rejectLog1_input",
      "sourceNodeId": "approvalDecision1",
      "sourcePort": "false",
      "targetNodeId": "rejectLog1",
      "targetPort": "input"
    },
    {
      "id": "edge_onboardLog1_success_endSuccess1_input",
      "sourceNodeId": "onboardLog1",
      "sourcePort": "success",
      "targetNodeId": "endSuccess1",
      "targetPort": "input"
    },
    {
      "id": "edge_rejectLog1_success_endRejected1_input",
      "sourceNodeId": "rejectLog1",
      "sourcePort": "success",
      "targetNodeId": "endRejected1",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start the process manually",
      "tags": [
        "trigger",
        "start",
        "manual"
      ],
      "sortOrder": 80,
